export type Unsubscribe = () => void;

export type TerminalAttachment = {
  sessionId: string;
  initialHistory?: Uint8Array;
};

export interface TerminalTransport {
  listSessions(): Promise<{ sessionId: string; worktreePath?: string | null }[]>;
  attach(sessionId: string): Promise<TerminalAttachment>;
  write(sessionId: string, data: string | Uint8Array): Promise<void> | void;
  resize(sessionId: string, cols: number, rows: number): Promise<void> | void;
  signal(sessionId: string, signal: "interrupt" | "terminate" | "kill"): Promise<void> | void;
  close(sessionId: string): Promise<void> | void;
  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe;
  onLifecycle(listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe;
}

import {
  closeTerminal,
  listTerminalSessions,
  onTerminalLifecycle,
  onTerminalOutput,
  resizeTerminal,
  signalTerminal,
  writeTerminal,
} from "../tauri";
import type { TerminalAttachment, TerminalTransport, Unsubscribe } from "./types";

export class TauriTerminalTransport implements TerminalTransport {
  async listSessions() {
    const sessions = await listTerminalSessions();
    return sessions.map((s) => ({
      sessionId: s.sessionId,
      worktreePath: s.worktreePath,
    }));
  }

  async attach(sessionId: string): Promise<TerminalAttachment> {
    return { sessionId };
  }

  async write(sessionId: string, data: string | Uint8Array) {
    const text = typeof data === "string" ? data : new TextDecoder().decode(data);
    await writeTerminal({ sessionId, data: text });
  }

  async resize(sessionId: string, cols: number, rows: number) {
    await resizeTerminal({ sessionId, cols, rows });
  }

  async signal(sessionId: string, signal: "interrupt" | "terminate" | "kill") {
    await signalTerminal({ sessionId, signal });
  }

  async close(sessionId: string) {
    await closeTerminal(sessionId);
  }

  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe {
    let unlisten: (() => void) | null = null;
    let cancelled = false;

    onTerminalOutput((payload) => {
      if (payload.sessionId === sessionId) {
        listener(payload.data);
      }
    }).then((fn) => {
      if (cancelled) {
        fn();
      } else {
        unlisten = fn;
      }
    });

    return () => {
      cancelled = true;
      if (unlisten) {
        unlisten();
      }
    };
  }

  onLifecycle(listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe {
    let unlisten: (() => void) | null = null;
    let cancelled = false;

    onTerminalLifecycle((payload) => {
      listener({
        sessionId: payload.sessionId,
        state: payload.state,
        exitCode: payload.exitCode,
      });
    }).then((fn) => {
      if (cancelled) {
        fn();
      } else {
        unlisten = fn;
      }
    });

    return () => {
      cancelled = true;
      if (unlisten) {
        unlisten();
      }
    };
  }
}

export const defaultTauriTransport = new TauriTerminalTransport();

import type { TerminalAttachment, TerminalTransport, Unsubscribe } from "./types";

export class WebSocketTerminalTransport implements TerminalTransport {
  private baseUrl: string;
  private token: string;
  private sockets: Map<string, WebSocket> = new Map();
  private outputListeners: Map<string, Set<(data: Uint8Array) => void>> = new Map();

  constructor(baseUrl: string, token: string) {
    this.baseUrl = baseUrl.replace(/\/$/, "");
    this.token = token;
  }

  async listSessions() {
    const res = await fetch(`${this.baseUrl}/api/v1/sessions?token=${encodeURIComponent(this.token)}`);
    if (!res.ok) throw new Error(`Failed to list sessions: ${res.statusText}`);
    const data = await res.json();
    return data.map((s: { sessionId: string }) => ({ sessionId: s.sessionId }));
  }

  async attach(sessionId: string): Promise<TerminalAttachment> {
    const wsProto = this.baseUrl.startsWith("https") ? "wss" : "ws";
    const host = this.baseUrl.replace(/^https?:\/\//, "");
    const wsUrl = `${wsProto}://${host}/api/v1/terminal/${sessionId}?token=${encodeURIComponent(this.token)}`;

    const ws = new WebSocket(wsUrl);
    ws.binaryType = "arraybuffer";

    const listeners = this.outputListeners.get(sessionId) ?? new Set();
    this.outputListeners.set(sessionId, listeners);

    ws.onmessage = (event) => {
      let data: Uint8Array;
      if (typeof event.data === "string") {
        data = new TextEncoder().encode(event.data);
      } else {
        data = new Uint8Array(event.data);
      }
      for (const listener of listeners) {
        listener(data);
      }
    };

    this.sockets.set(sessionId, ws);
    return { sessionId };
  }

  write(sessionId: string, data: string | Uint8Array) {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    const bytes = typeof data === "string" ? new TextEncoder().encode(data) : data;
    ws.send(bytes);
  }

  resize(sessionId: string, cols: number, rows: number) {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: "resize", cols, rows }));
  }

  signal(sessionId: string, signal: "interrupt" | "terminate" | "kill") {
    const ws = this.sockets.get(sessionId);
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: "signal", signal }));
  }

  async close(sessionId: string) {
    const ws = this.sockets.get(sessionId);
    if (ws) {
      ws.close();
      this.sockets.delete(sessionId);
    }
  }

  onOutput(sessionId: string, listener: (data: string | Uint8Array) => void): Unsubscribe {
    const listeners = this.outputListeners.get(sessionId) ?? new Set();
    const wrapped = (bytes: Uint8Array) => listener(bytes);
    listeners.add(wrapped);
    this.outputListeners.set(sessionId, listeners);

    return () => {
      listeners.delete(wrapped);
    };
  }

  onLifecycle(_listener: (event: { sessionId: string; state: string; exitCode?: number | null }) => void): Unsubscribe {
    return () => {};
  }
}

import type { PaneDirection, PaneNode } from "../state/paneTree";

export type WorktreeIdentity = {
  wsId: string;
  slug: string;
};

export type Worktree = {
  path: string;
  head: string;
  branch: string | null;
  bare: boolean;
  detached: boolean;
  locked: string | null;
  prunable: string | null;
};

export function worktreeIdentity(worktree: Worktree): WorktreeIdentity | null {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "");
  const parts = branch?.split("/");
  if (!parts || parts.length < 3 || parts[0] !== "orca") return null;

  return { wsId: parts[1], slug: parts.slice(2).join("/") };
}

export type DirtyFile = {
  statusCode: string;
  path: string;
};

export type DirtyState = {
  isDirty: boolean;
  files: DirtyFile[];
};

export type BranchDeletionPreview = {
  branch: string;
  head: string;
  upstream: string | null;
  merged: boolean;
  ahead: number | null;
  behind: number | null;
};

export type TerminalSignal = "interrupt" | "terminate" | "kill";

export type TerminalSessionSummary = {
  sessionId: string;
  worktreePath: string | null;
};

export type TerminalLifecycle = "starting" | "working" | "waiting" | "exited" | "failed";

export type TerminalSession = {
  /** Frontend-local stable identity used by pane leaves and terminal renderer ownership. */
  id: string;
  /** Best known process CWD. It may be nested below the worktree root after `cd`. */
  cwd: string;
  /** Stable worktree/repository root. Optional only for v1/test-state compatibility. */
  worktreePath?: string;
  workspaceId: string;
  worktree: WorktreeIdentity | null;
  /** Native PTY identity. This is intentionally distinct from `id`. */
  backendSessionId: string | null;
  lifecycle: TerminalLifecycle;
  ownerId?: string | null;
};

export type TerminalTab = {
  kind?: "terminal";
  id: string;
  label: string;
  /** Compatibility primary session; every real pane leaf is authoritative in TabPaneLayout. */
  sessionId: string;
  pinned?: boolean;
};

export type BrowserProfileId = "default" | "private";

export type LogicalRect = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type BrowserState = {
  browserId: string;
  webviewLabel: string;
  workspaceId?: string | null;
  worktreePath?: string | null;
  profileId: BrowserProfileId;
  generation: number;
  url: string;
  title?: string | null;
  loading: boolean;
  canGoBack: boolean;
  canGoForward: boolean;
  zoomFactor: number;
  loadError?: string | null;
  visible: boolean;
};

export type BrowserTab = {
  kind: "browser";
  id: string;
  label: string;
  browserId: string;
  url: string;
  title?: string | null;
  loading?: boolean;
  canGoBack?: boolean;
  canGoForward?: boolean;
  profileId?: string;
  worktreePath?: string;
  worktreeLabel?: string;
  pinned?: boolean;
};

export type WorkspaceTab = TerminalTab | BrowserTab;

export type CreateBrowserRequest = {
  workspaceId?: string | null;
  worktreePath?: string | null;
  url: string;
  profile?: BrowserProfileId;
  bounds?: LogicalRect;
  visible?: boolean;
};

export type BrowserSessionSummary = {
  browserId: string;
  webviewLabel: string;
  workspaceId?: string | null;
  profileId?: string | null;
  url: string;
  title?: string | null;
  visible: boolean;
};

export type Pane = {
  id: string;
  tabId: string;
};

export type SplitMode = "none" | "horizontal" | "vertical";

export type NestedSplit = {
  orientation: Exclude<SplitMode, "none">;
  tabId: string;
};

export type TerminalPaneContent = {
  readonly kind: "terminal";
  readonly sessionId: string;
};

export type BrowserPaneState = {
  readonly browserId: string;
  readonly url: string;
  readonly title?: string | null;
  readonly loading?: boolean;
  readonly canGoBack?: boolean;
  readonly canGoForward?: boolean;
  readonly profileId?: string;
  readonly worktreePath?: string;
  readonly worktreeLabel?: string;
};

export type BrowserPaneContent = {
  readonly kind: "browser";
  readonly browser?: BrowserPaneState;
  readonly browserId?: string;
  readonly url?: string;
  readonly title?: string | null;
  readonly loading?: boolean;
  readonly canGoBack?: boolean;
  readonly canGoForward?: boolean;
  readonly profileId?: string;
  readonly worktreePath?: string;
  readonly worktreeLabel?: string;
};

export type PaneContent = TerminalPaneContent | BrowserPaneContent;

export function createBrowserPaneContent(browser: BrowserPaneState): BrowserPaneContent {
  const content: BrowserPaneContent = {
    kind: "browser",
    browser: { ...browser },
  };
  Object.defineProperties(content, {
    browserId: { get() { return this.browser.browserId; }, enumerable: false },
    url: { get() { return this.browser.url; }, enumerable: false },
    title: { get() { return this.browser.title; }, enumerable: false },
    loading: { get() { return this.browser.loading; }, enumerable: false },
    canGoBack: { get() { return this.browser.canGoBack; }, enumerable: false },
    canGoForward: { get() { return this.browser.canGoForward; }, enumerable: false },
    profileId: { get() { return this.browser.profileId; }, enumerable: false },
    worktreePath: { get() { return this.browser.worktreePath; }, enumerable: false },
    worktreeLabel: { get() { return this.browser.worktreeLabel; }, enumerable: false },
  });
  return content;
}

export function createTerminalPaneContent(sessionId: string): TerminalPaneContent {
  return {
    kind: "terminal",
    sessionId,
  };
}

/**
 * The split arrangement inside a single terminal tab. This is intentionally separate
 * from TabGroupLayoutNode: Orca keeps terminal panes inside a tab and split tab groups
 * as two different layout layers.
 */
export type TabPaneLayout = {
  root: PaneNode;
  /** Leaf that receives keyboard focus inside this tab. */
  activeLeafId: string | null;
  /** Leaf temporarily zoomed to fill the tab, or `null` when every pane is visible. */
  expandedLeafId: string | null;
  /** Frontend-local terminal session rendered by each leaf of `root`. */
  sessionIdsByLeafId: Record<string, string>;
  /** Authoritative content map for each leaf of `root`. */
  contentsByLeafId?: Record<string, PaneContent>;
};

export type TabGroup = {
  id: string;
  tabIds: string[];
  activeTabId: string | null;
};

export type TabGroupLayoutNode =
  | { type: "group"; groupId: string }
  | {
      type: "split";
      direction: PaneDirection;
      first: TabGroupLayoutNode;
      second: TabGroupLayoutNode;
      ratio: number;
    };

export type LayoutState = {
  tabs: WorkspaceTab[];
  primaryTabId?: string | null;
  secondaryTabId?: string | null;
  split?: SplitMode;
  nestedSplit?: NestedSplit | null;
  /** Active tab in the currently focused tab group. */
  activeTabId: string | null;
  /** Terminal-pane tree owned independently by each tab. */
  layoutsByTabId: Record<string, TabPaneLayout>;
  /** Orca-style tab groups. Optional only for backwards-compatible persisted/test state. */
  tabGroups?: Record<string, TabGroup>;
  /** Split tree whose leaves are tab groups, not terminal panes. */
  tabGroupLayout?: TabGroupLayoutNode | null;
  focusedGroupId?: string | null;
};

export type AgentState = "starting" | "working" | "waiting" | "exited" | "failed";

export type ActiveAgent = {
  id: string;
  name: string;
  task: string;
  state: AgentState;
  worktree: WorktreeIdentity | null;
  worktreePath: string;
  sessionId: string;
};

export type TerminalOutputPayload = {
  sessionId: string;
  data: string;
};

export type TerminalLifecyclePayload = {
  sessionId: string;
  state: "started" | "exited" | "failed";
  exitCode: number | null;
  reason: string | null;
};

export type WorktreeChangedPayload = {
  workspaceId: string;
  worktree: WorktreeIdentity;
  kind: "created" | "deleted" | "destructivelyDeleted" | "dirtyChanged" | "pruned";
};

export type NotificationSource = "agent-task-complete" | "terminal-bell" | "system";
export type NotificationAuthorization = "not-determined" | "denied" | "authorized" | "provisional" | "unknown";
export type NotificationPlatform = "macos" | "windows" | "linux" | "unknown";

export interface NotificationPermissionStatus {
  platform?: NotificationPlatform;
  supported?: boolean;
  authorization: NotificationAuthorization;
  alertsEnabled?: boolean | null;
  soundsEnabled?: boolean | null;
  requested?: boolean;
  authoritative?: boolean;
  canOpenSettings?: boolean;
  status?: string;
}

export interface NotificationPermissionRequest {
  granted: boolean;
  status?: NotificationPermissionStatus;
  error?: string | null;
}

export interface DispatchNotificationArgs {
  source?: NotificationSource | string;
  title?: string;
  body?: string;
  notificationId?: string;
  workspaceLabel?: string;
  worktreeLabel?: string;
  terminalTitle?: string;
  agentLabel?: string;
}

export interface DispatchNotificationResult {
  submitted?: boolean;
  delivered?: boolean;
  reason?: "permission-required" | "blocked-by-system" | "unsupported" | "backend-error" | string;
}

export interface NotificationProbeResult {
  outcome?: "submitted" | "ready" | "permission-required" | "blocked-by-system" | "unsupported" | "failed" | string;
  status?: NotificationPermissionStatus;
  testSubmitted?: boolean;
  success?: boolean;
}

export interface OpenSystemSettingsResult {
  opened: boolean;
  reason?: string | null;
}

export interface PlaySoundResult {
  played: boolean;
  reason?: string | null;
}

export interface PickedAudioFile {
  path: string;
  displayName?: string;
  extension?: string;
  sizeBytes?: number;
}

export type StructuredIpcError = {
  code: string;
  message: string;
  details?: Record<string, unknown>;
};

export interface PersistedWorktree {
  path: string;
  branch: string;
  head: string;
  isMain: boolean;
  isLocked: boolean;
}

/** Version-2 terminal tab payload. All IDs in pane mappings are frontend-local session IDs. */
export interface PersistedTerminalTabState {
  primarySessionId: string;
  paneTree: PaneNode;
  sessionIdsByLeafId: Record<string, string>;
  contentsByLeafId?: Record<string, PaneContent>;
  activeLeafId: string | null;
  expandedLeafId: string | null;
}

export interface PersistedBrowserTabState {
  browserId: string;
  url: string;
  title?: string | null;
  loading?: boolean;
  canGoBack?: boolean;
  canGoForward?: boolean;
  profileId?: string;
  worktreePath?: string;
  worktreeLabel?: string;
}

/**
 * Version-2 tab record. Legacy v1 fields remain optional so persisted sessions can be
 * migrated in place without unsafe casts or a second DTO hierarchy.
 */
export interface PersistedTab {
  id: string;
  label: string;
  kind?: "terminal" | "browser";
  pinned?: boolean;
  terminal?: PersistedTerminalTabState;
  browser?: PersistedBrowserTabState;
  customTitle?: string;

  // v1 compatibility fields
  sessionId?: string;
  worktreePath?: string;
  paneTree?: PaneNode;
  sessionIdsByLeafId?: Record<string, string>;
  contentsByLeafId?: Record<string, PaneContent>;
  activeLeafId?: string | null;
  expandedLeafId?: string | null;
}

export interface PersistedTabGroup {
  id: string;
  tabIds: string[];
  activeTabId: string | null;
}

export interface PersistedLayout {
  splitMode: string;
  primaryTabId: string | null;
  secondaryTabId: string | null;
  activeTabId: string | null;
  tabs: PersistedTab[];
  tabGroups?: PersistedTabGroup[];
  tabGroupLayout?: TabGroupLayoutNode | null;
  focusedGroupId?: string | null;
  layoutsByTabId?: Record<string, TabPaneLayout>;
}

export interface PersistedTerminalSession {
  /** v2 stable frontend identity; map key remains authoritative. */
  localSessionId?: string;
  /** v2 native PTY identity. `null` means it must be respawned on restore. */
  backendSessionId?: string | null;
  /** v1 compatibility field (v1 accidentally stored the local id here). */
  sessionId?: string;
  worktreePath: string;
  cwd: string;
  lastCommand?: string;
  recentScrollback?: string;
  createdAt: number;
}

export interface PersistedWorkspace {
  workspaceId: string;
  repoRoot: string;
  worktrees: PersistedWorktree[];
  activeWorktreePath: string | null;
  layout: PersistedLayout;
  worktreeLayouts?: Record<string, PersistedLayout>;
  terminalSessions: Record<string, PersistedTerminalSession>;
}

export interface PersistedWorkspaceSession {
  version: number;
  timestamp: number;
  activeWorkspaceId: string;
  workspaces: Record<string, PersistedWorkspace>;
}

export const DEFAULT_TERMINAL_FONT_STACK = 'MesloLGS NF, "Noto Sans KR", monospace';
