pub async fn cmd_terminal_resize(
    terminal_service: State<'_, Arc<TerminalService>>,
    session_id: String,
    cols: u16,
    rows: u16,
) -> Result<(), IpcError> {
    terminal_service
        .resize(&session_id, cols, rows)
        .map_err(IpcError::from)
}

